import sys
from collections import defaultdict, deque

def find_custom_alphabet(n, names):
    graph = defaultdict(list)
    in_degree = {chr(i): 0 for i in range(ord('a'), ord('z') + 1)}

    for i in range(n - 1):
        for j in range(min(len(names[i]), len(names[i + 1]))):
            if names[i][j] != names[i + 1][j]:
                graph[names[i][j]].append(names[i + 1][j])
                in_degree[names[i + 1][j]] += 1
                break
        else:
            if len(names[i]) > len(names[i + 1]):
                return "Impossible"

    queue = deque([char for char in in_degree if in_degree[char] == 0])
    result = []

    while queue:
        current = queue.popleft()
        result.append(current)
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) == 26:
        return ''.join(result)
    else:
        return "Impossible"

input = sys.stdin.read().strip().split('\n')
n = int(input[0])
names = input[1:]
print(find_custom_alphabet(n, names))
